6: #[derive(Default)]
7: pub struct Published {
8:     value: AtomicUsize,
9:     ready: AtomicBool,
10: }
11: impl Published {
12:     /// The caller publishes at most once, from one writer.
13:     pub fn publish(&self, value: usize) {
14:         self.value.store(value, Ordering::Relaxed);
15:         self.ready.store(true, Ordering::Release);
16:     }
17:     pub fn snapshot(&self) -> Option<usize> {
18:         self.ready
19:             .load(Ordering::Acquire)
20:             .then(|| self.value.load(Ordering::Relaxed))
21:     }
22: }

