11:     let executions = std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0));
12:     let seen = executions.clone();
13:     builder.check(move || {
14:         seen.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
15:         let data = loom::sync::Arc::new(Published::default());
16:         let writer = data.clone();
17:         let task = loom::thread::spawn(move || writer.publish(42));
18:         if let Some(value) = data.snapshot() {
19:             assert_eq!(value, 42);
20:         }
21:         task.join().unwrap();
22:         assert_eq!(data.snapshot(), Some(42));
23:     });
24:     let count = executions.load(std::sync::atomic::Ordering::SeqCst);
25:     println!("completed model executions: {count}");
26:     assert!(count > 1);
